CREATE TABLE STOCK (
  ITEM_CD  VARCHAR2(10) PRIMARY KEY,
  WH_CD    VARCHAR2(5)  NOT NULL,
  QTY      NUMBER       DEFAULT 0 CHECK (QTY >= 0)
);

CREATE TABLE STOCK_TMP AS SELECT * FROM STOCK WHERE 1 = 2;

